from urllib.parse import urlparse
from flask import request, redirect, abort

ALLOWED_HOSTS = {'app.example.com', 'dashboard.example.com'}

@app.route('/login')
def login_redirect():
    next_url = request.args.get('next', '/dashboard')

    # VULNERABLE: redirect to any URL, including external domains
    # return redirect(next_url)

    # SECURE: validate that redirect stays within allowed hosts
    parsed = urlparse(next_url)
    # Allow relative URLs and approved hosts only
    if parsed.netloc and parsed.netloc not in ALLOWED_HOSTS:
        abort(400, 'Invalid redirect destination')
    # Ensure relative URLs don't start with // (protocol-relative)
    if next_url.startswith('//'):
        abort(400, 'Invalid redirect destination')
    return redirect(next_url)

