// SAFE — parameterized query: user value travels in a separate channel
async function getUserSafe(username) {
  const sql = 'SELECT * FROM users WHERE username = $1';
  // $1 is a typed placeholder; the DB treats 'username' as data, never code
  return db.query(sql, [username]);
}

