// Check submitted password against known-breached list (k-anonymity)
async function isBreachedPassword(password) {
  const hash = await crypto.subtle.digest('SHA-1',
    new TextEncoder().encode(password));
  const hex = [...new Uint8Array(hash)]
    .map(b => b.toString(16).padStart(2, '0')).join('').toUpperCase();
  const prefix = hex.slice(0, 5);
  const res = await fetch(`https://api.pwnedpasswords.com/range/${prefix}`);
  const text = await res.text();
  return text.includes(hex.slice(5));
}

// Middleware: verify the JWT signature (authentication)
function authenticate(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Unauthenticated' });
  req.user = jwt.verify(token, process.env.JWT_PUBLIC_KEY);
  next();
}

// Middleware: check the user owns this resource (authorization)
function authorizeOwner(req, res, next) {
  if (req.user.sub !== req.params.userId)
    return res.status(403).json({ error: 'Forbidden' });
  next();
}

// Correct: check authorization after authentication
app.get('/api/orders/:id', authenticate, async (req, res) => {
  const order = await db.getOrder(req.params.id);
  if (!order) return res.status(404).json({ error: 'Not found' });

  // Authorization check — does this user own this order?
  if (order.userId !== req.user.sub)
    return res.status(403).json({ error: 'Forbidden' });

  res.json(order);
});

// Check if submitted credentials appear in breach data before authenticating
async function login(email, password) {
  if (await isBreachedPassword(password)) {
    // Force reset — don't authenticate with known-leaked credentials
    return { action: 'force_reset', reason: 'breached_credential' };
  }
  const user = await db.findUser(email);
  if (!user || !await argon2.verify(user.passwordHash, password))
    return { action: 'deny' };
  return { action: 'allow', userId: user.id };
}

